// --- M1-20 -------------------------------------------------------------------------------------
const answerOf = (
  input: Record<string, unknown>,
  vhost: FakeVhost,
  options: FakeOptions = {},
) =>
  runQuery(
    routingDeadLetter,
    createRoutingDeadLetterAction,
    { vhost: '/', ...input },
    { ...options, vhosts: { '/': vhost } },
  );

/** Two queues that expire into each other through a pair of direct exchanges. */
const ring: FakeVhost = {
  exchanges: [
    { name: 'xa', type: 'direct' },
    { name: 'xb', type: 'direct' },
  ],
  queues: [
    {
      name: 'a',
      type: 'classic',
      arguments: {
        'x-message-ttl': 1_000,
        'x-dead-letter-exchange': 'xb',
        'x-dead-letter-routing-key': 'b',
      },
      policy: null,
      operator_policy: null,
    },
    {
      name: 'b',
      type: 'classic',
      arguments: {
        'x-message-ttl': 1_000,
        'x-dead-letter-exchange': 'xa',
        'x-dead-letter-routing-key': 'a',
      },
      policy: null,
      operator_policy: null,
    },
    {
      name: 'solo',
      type: 'classic',
      arguments: { 'x-message-ttl': 1_000 },
      policy: null,
      operator_policy: null,
    },
  ],
  bindings: [
    { source: 'xa', destination: 'a', routing_key: 'a' },
    { source: 'xb', destination: 'b', routing_key: 'b' },
  ],
};

describe('M1-20 AC-9 dead-letter drop loop and retry ring are told apart', () => {
  it('reports a ring that nobody can reject as a drop loop, and the path ends where the broker drops it', async () => {
    const { output } = await answerOf({ queue: 'a' }, ring);

    expect(output.loops).toEqual([
      { queues: ['a', 'b'], queuesMore: 0, kind: 'drop-loop', possible: false },
    ]);
    expect(output.paths).toHaveLength(1);
    expect(output.paths[0]?.steps.map((s) => s.from)).toEqual(['a', 'b']);
    // b dead-letters back into a, which has already seen the message: the broker drops it there.
    expect(output.paths[0]?.end).toEqual({ kind: 'dropped-cycle', queue: 'b' });
    // What a dead letter from a can reach: b. The return to a is removed by the cycle rule.
    expect(output.reached).toEqual(['b']);
    expect(output.exact).toBe(true);
    expect(output.consumers).toBe('read');
  });

  it('reports the same ring as a retry ring when a consumer of it can reject', async () => {
    const { output } = await answerOf(
      { queue: 'a' },
      { ...ring, consumers: { acking: ['b'] } },
    );

    expect(output.loops).toMatchObject([
      { queues: ['a', 'b'], kind: 'retry-ring' },
    ]);
  });

  it('lists only the loops that include the queue', async () => {
    const { output } = await answerOf({ queue: 'solo' }, ring);

    expect(output.loops).toEqual([]);
    // A queue with a TTL and no dead-letter exchange drops what expires.
    expect(output.paths[0]?.end).toEqual({
      kind: 'dropped-no-dead-letter',
      queue: 'solo',
    });
  });

  it('takes a reason and the routing keys of the message', async () => {
    const { output } = await answerOf(
      { queue: 'a', reason: 'expired', keys: ['k'] },
      ring,
    );

    expect(output.paths).toHaveLength(1);
    expect(output.paths[0]?.steps[0]).toMatchObject({
      reasons: ['expired'],
      exchange: 'xb',
    });
  });

  it('says a queue that the vhost does not have is not found', async () => {
    await expect(answerOf({ queue: 'nope' }, ring)).rejects.toMatchObject({
      code: 'NOT_FOUND',
    });
  });

  it('is not exact while a policy that could set the dead-letter exchange was not readable', async () => {
    const { output } = await answerOf(
      { queue: 'solo' },
      { ...ring, policies: 'forbidden' },
    );

    expect(output.exact).toBe(false);
    expect(output.gaps).toContain('policy-unreadable');
    // Nothing is walked from a guess: the setting is unknown and the walk says so.
    expect(output.paths[0]?.end).toMatchObject({
      kind: 'indeterminate',
      why: 'dead-letter-unknown',
    });
  });

  it('keeps the numbers of what the walk cut', async () => {
    const { output } = await answerOf({ queue: 'a' }, ring);

    expect(output.truncation).toEqual({
      sources: 0,
      steps: 0,
      paths: 0,
      loops: 0,
      candidates: 0,
    });
    expect(output.loopsTruncation.loops).toBe(0);
  });
});

describe('M1-20 AC-4 the dead-letter walk takes the reason and the keys the caller knows', () => {
  const vhost: FakeVhost = {
    exchanges: [{ name: 'dx', type: 'direct' }],
    queues: [
      {
        name: 'multi',
        type: 'classic',
        arguments: {
          'x-message-ttl': 1_000,
          'x-max-length': 10,
          'x-dead-letter-exchange': 'dx',
        },
        policy: null,
        operator_policy: null,
      },
      { name: 't1', type: 'classic', policy: null, operator_policy: null },
      { name: 't2', type: 'classic', policy: null, operator_policy: null },
    ],
    bindings: [
      { source: 'dx', destination: 't1', routing_key: 'k1' },
      { source: 'dx', destination: 't2', routing_key: 'k2' },
    ],
  };

  it('walks one reason when asked, and every reason of the queue when not', async () => {
    const all = await answerOf({ queue: 'multi' }, vhost);
    const one = await answerOf({ queue: 'multi', reason: 'maxlen' }, vhost);

    expect(all.output.paths[0]?.steps[0]?.reasons).toEqual([
      'expired',
      'maxlen',
    ]);
    expect(one.output.paths[0]?.steps[0]?.reasons).toEqual(['maxlen']);
  });

  it('walks every binding as a possibility without the keys, and exactly with them', async () => {
    const open = await answerOf({ queue: 'multi' }, vhost);
    const known = await answerOf({ queue: 'multi', keys: ['k1'] }, vhost);

    expect(open.output.exact).toBe(false);
    expect(open.output.paths[0]?.steps[0]).toMatchObject({
      keys: 'original',
      targets: [
        { queue: 't1', certainty: 'possible' },
        { queue: 't2', certainty: 'possible' },
      ],
    });
    expect(known.output.exact).toBe(true);
    expect(known.output.paths[0]?.steps[0]).toMatchObject({
      keys: ['k1'],
      targets: [{ queue: 't1', certainty: 'definite' }],
    });
  });

  it('is not exact when a policy list was not readable, even if the walk itself is exact', async () => {
    const { output } = await answerOf(
      { queue: 'a' },
      { ...ring, policies: 'forbidden' },
    );

    // Both queues name their dead-letter exchange and key as arguments, so the walk is complete...
    expect(output.paths[0]?.end).toEqual({ kind: 'dropped-cycle', queue: 'b' });
    // ...but a policy that could change the limits was not read.
    expect(output.gaps).toContain('policy-unreadable');
    expect(output.exact).toBe(false);
  });

  it('says whether the consumers that tell a retry ring from a drop loop were read', async () => {
    const { output } = await answerOf(
      { queue: 'a' },
      { ...ring, consumers: 'forbidden' },
    );

    expect(output.consumers).toBe('unreadable');
    expect(output.loops[0]?.kind).toBe('drop-loop');
  });
});
